// Groups draft pre-bills by the matter's responsible attorney -- each attorney gets one review
// email listing everything they need to review this cycle, rather than one email per bill.
const bills = $input.first().json.data || [];
const groups = {};

for (const bill of bills) {
  const attorney = (bill.matter && bill.matter.responsible_attorney) || {};
  const key = attorney.email || 'unassigned';
  if (!groups[key]) {
    groups[key] = { attorney_name: attorney.name || 'Unassigned', attorney_email: attorney.email || '', bills: [] };
  }
  groups[key].bills.push({
    bill_id: bill.id,
    bill_number: bill.number || '',
    total: Number(bill.total || 0),
    matter_ref: (bill.matter && bill.matter.display_number) || '',
    matter_description: (bill.matter && bill.matter.description) || '',
    client_name: (bill.client && bill.client.name) || '',
  });
}

const unassigned_count = (groups['unassigned'] || { bills: [] }).bills.length;
const attorney_groups = Object.entries(groups)
  .filter(([key]) => key !== 'unassigned')
  .map(([, g]) => g);

return [{ json: {
  attorney_groups,
  has_draft_prebills: attorney_groups.length > 0,
  unassigned_count,
} }];

const FIRM_NAME = $vars.FIRM_NAME;
const FIRM_FROM_EMAIL = $vars.FIRM_FROM_EMAIL;
const BILLING_URL = $vars.FIRM_CLIO_BILLING_URL || 'https://app.clio.com/bills?status=draft';
const REMINDER_DAYS = $vars.FIRM_PREBILL_REMINDER_DAYS || '5';

if (!FIRM_NAME) throw new Error('FIRM_NAME n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');

const item = $input.first().json;
const bills = item.bills;
const total = bills.reduce((s, b) => s + b.total, 0);
const lines = bills.map(b => `  • ${b.matter_ref} — ${b.client_name} — $${b.total.toFixed(2)}${b.matter_description ? ' (' + b.matter_description + ')' : ''}`);

const subject = `${bills.length} pre-bill(s) ready for your review`;
const body = `Hi ${item.attorney_name},

You have ${bills.length} draft pre-bill(s) ready for your review this cycle (total $${total.toFixed(2)}):

${lines.join('\n')}

Review, edit, and finalize each one directly in Clio:
${BILLING_URL}

Please review these promptly — an automatic reminder will follow for anything still outstanding after ${REMINDER_DAYS} days.

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: item.attorney_email,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: body,
  template_id: 'PAC-61',
  matter_id: '',
} }];

// Nudges based on each pre-bill's OWN age (days sitting in draft), not a shared firm-wide
// deadline -- Clio doesn't expose a due date on a draft bill (that only gets set once a bill
// is finalized and issued), so 'how long has this specific bill been waiting for review' is the
// real signal available, and it's driven entirely by Clio's own timestamp on each bill.
const REMINDER_DAYS = Number($vars.FIRM_PREBILL_REMINDER_DAYS) || 5;
const URGENT_DAYS = Number($vars.FIRM_PREBILL_URGENT_DAYS) || 10;
const ESCALATE_DAYS = Number($vars.FIRM_PREBILL_ESCALATE_DAYS) || 15;
const ESCALATE_REPEAT_DAYS = Number($vars.FIRM_PREBILL_ESCALATE_REPEAT_DAYS) || 5;

const bills = $input.first().json.data || [];
const today = new Date();
today.setHours(0, 0, 0, 0);
const msPerDay = 24 * 60 * 60 * 1000;

const due_bills = [];
for (const bill of bills) {
  const attorney = (bill.matter && bill.matter.responsible_attorney) || {};
  if (!attorney.email) continue; // nobody to nudge
  if (!bill.created_at) continue; // can't compute age without a timestamp -- see notes on the fetch step

  const created = new Date(bill.created_at);
  created.setHours(0, 0, 0, 0);
  const daysInDraft = Math.floor((today - created) / msPerDay);

  // Exact-day matches for reminder/urgent avoid re-nudging the same bill every single day once
  // past the threshold. 'overdue' repeats every ESCALATE_REPEAT_DAYS after the initial escalation
  // so the partner keeps hearing about it until it's actually resolved, rather than escalating once
  // and going silent.
  let tier = 'none';
  if (daysInDraft === REMINDER_DAYS) tier = 'reminder';
  else if (daysInDraft === URGENT_DAYS) tier = 'urgent';
  else if (daysInDraft >= ESCALATE_DAYS && (daysInDraft - ESCALATE_DAYS) % ESCALATE_REPEAT_DAYS === 0) tier = 'overdue';

  if (tier === 'none') continue;

  due_bills.push({
    bill_id: bill.id,
    bill_number: bill.number || '',
    total: Number(bill.total || 0),
    matter_ref: (bill.matter && bill.matter.display_number) || '',
    matter_description: (bill.matter && bill.matter.description) || '',
    client_name: (bill.client && bill.client.name) || '',
    attorney_name: attorney.name || 'Unassigned',
    attorney_email: attorney.email,
    days_in_draft: daysInDraft,
    tier,
  });
}

return [{ json: { due_bills, has_due_bills: due_bills.length > 0 } }];

// Collects every overdue bill that reached this branch in this run (not just one item) and
// groups them by attorney, so one attorney with three overdue bills produces one escalation
// email listing all three, not three separate emails.
const items = $input.all();
const groups = {};
for (const item of items) {
  const b = item.json;
  const key = b.attorney_email;
  if (!groups[key]) groups[key] = { attorney_name: b.attorney_name, attorney_email: b.attorney_email, bills: [] };
  groups[key].bills.push(b);
}
return Object.values(groups).map(g => ({ json: g }));

const FIRM_NAME = $vars.FIRM_NAME;
const PARTNER_EMAIL = $vars.FIRM_PARTNER_EMAIL;
const FIRM_FROM_EMAIL = $vars.FIRM_FROM_EMAIL;
const BILLING_URL = $vars.FIRM_CLIO_BILLING_URL || 'https://app.clio.com/bills?status=draft';

if (!PARTNER_EMAIL) throw new Error('FIRM_PARTNER_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');

const item = $input.first().json;
const bills = item.bills;
const total = bills.reduce((s, b) => s + b.total, 0);
const lines = bills.map(b => `  • ${b.matter_ref} — ${b.client_name} — $${b.total.toFixed(2)} — in draft ${b.days_in_draft} day(s)`);

const subject = `${item.attorney_name} has ${bills.length} pre-bill(s) stuck in draft`;
const body = `${item.attorney_name} (${item.attorney_email}) has ${bills.length} draft pre-bill(s) that have been sitting unreviewed for a while (total $${total.toFixed(2)}):

${lines.join('\n')}

Review directly in Clio:
${BILLING_URL}

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: PARTNER_EMAIL,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: body,
  template_id: 'PAC-61',
  matter_id: '',
} }];

// Same grouping as 'Group Overdue Bills By Attorney', for reminder/urgent tier bills instead.
const items = $input.all();
const groups = {};
for (const item of items) {
  const b = item.json;
  const key = b.attorney_email;
  if (!groups[key]) groups[key] = { attorney_name: b.attorney_name, attorney_email: b.attorney_email, bills: [] };
  groups[key].bills.push(b);
}
return Object.values(groups).map(g => ({ json: g }));

const FIRM_NAME = $vars.FIRM_NAME;
const FIRM_FROM_EMAIL = $vars.FIRM_FROM_EMAIL;
const BILLING_URL = $vars.FIRM_CLIO_BILLING_URL || 'https://app.clio.com/bills?status=draft';

if (!FIRM_FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');

const item = $input.first().json;
const bills = item.bills;
const total = bills.reduce((s, b) => s + b.total, 0);
const lines = bills.map(b => `  • ${b.matter_ref} — ${b.client_name} — $${b.total.toFixed(2)} — in draft ${b.days_in_draft} day(s)`);

// This attorney's bills can be a mix of 'reminder' and 'urgent' tier -- label the email by the
// most urgent tier present so the subject reflects the most pressing item.
const mostUrgent = bills.some(b => b.tier === 'urgent') ? 'urgent' : 'reminder';
const TIER_COPY = { reminder: 'A friendly nudge', urgent: 'An urgent reminder' };

const subject = `${TIER_COPY[mostUrgent]}: ${bills.length} pre-bill(s) still need your review`;
const body = `Hi ${item.attorney_name},

You have ${bills.length} draft pre-bill(s) still waiting for your review (total $${total.toFixed(2)}):

${lines.join('\n')}

Review and finalize in Clio:
${BILLING_URL}

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: item.attorney_email,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: body,
  template_id: 'PAC-61',
  matter_id: '',
} }];
